N = 3
# Assignment: f(i, j) = (i-1)*N + j for 1-based indexing (i=row, j=col)
grid = [[0] * N for _ in range(N)]
for i in range(N):
    for j in range(N):
        # Value is 1-indexed
        grid[i][j] = i * N + j + 1

def check_starting_field(i, j, grid, N):
    val = grid[i][j]
    # Check neighbors: (i-1, j), (i+1, j), (i, j-1), (i, j+1)
    neighbors = []

    # Directions: Up, Down, Left, Right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for di, dj in directions:
        ni, nj = i + di, j + dj

        # Check bounds
        if 0 <= ni < N and 0 <= nj < N:
            neighbors.append(grid[ni][nj])

    # Condition (i): only adjacent to fields with larger numbers
    for neighbor_val in neighbors:
        if neighbor_val < val:
            return False # Found a smaller neighbor

    return True # All neighbors are larger or there are no neighbors (N=1)

starting_fields_count = 0
for i in range(N):
    for j in range(N):
        if check_starting_field(i, j, grid, N):
            starting_fields_count += 1

print(f"For N={N} using row-major assignment, the number of starting fields is: {starting_fields_count}")
